<script>
(()=>{'use strict';const root=document.querySelector('[data-na]');if(!root)return;root.__naCleanup?.();const tabs=[...root.querySelectorAll('[data-na-tab]')],panels=[...root.querySelectorAll('[data-na-panel]')],list=root.querySelector('.na-selector'),reduce=matchMedia('(prefers-reduced-motion: reduce)'),off=[],animations=new Set();let index=0,observer;
const on=(el,type,fn)=>{el.addEventListener(type,fn);off.push(()=>el.removeEventListener(type,fn));};
function stop(){animations.forEach(a=>a.cancel());animations.clear();}
function animate(el,frames,options){if(reduce.matches||typeof el.animate!=='function')return;const a=el.animate(frames,options);animations.add(a);a.onfinish=a.oncancel=()=>animations.delete(a);}
function select(next,focus=false,motion=true){stop();index=next;tabs.forEach((t,i)=>{t.setAttribute('aria-selected',String(i===next));t.tabIndex=i===next?0:-1;panels[i].hidden=i!==next;});if(focus)tabs[next].focus();if(motion)animate(panels[next],[{opacity:0,transform:'translateY(9px)'},{opacity:1,transform:'translateY(0)'}],{duration:400,easing:'cubic-bezier(.16,1,.3,1)'});}
panels.forEach((p,i)=>{p.setAttribute('role','tabpanel');p.setAttribute('aria-labelledby',tabs[i].id);p.tabIndex=0;});tabs.forEach((t,i)=>{on(t,'click',()=>{if(index!==i)select(i);});on(t,'keydown',e=>{let n=null;if(e.key==='ArrowRight')n=(i+1)%tabs.length;if(e.key==='ArrowLeft')n=(i+tabs.length-1)%tabs.length;if(e.key==='Home')n=0;if(e.key==='End')n=tabs.length-1;if(n!==null){e.preventDefault();select(n,true);}});});root.classList.add('is-enhanced');list.hidden=false;select(0,false,false);on(reduce,'change',stop);
if(typeof IntersectionObserver==='function'){observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(!e.isIntersecting)return;animate(e.target,[{opacity:0,translate:'0 16px'},{opacity:1,translate:'0 0'}],{duration:650,easing:'cubic-bezier(.16,1,.3,1)'});observer.unobserve(e.target);});},{threshold:.12});observer.observe(root.querySelector('.na-heading'));observer.observe(panels[0]);}
root.__naCleanup=()=>{observer?.disconnect();stop();off.forEach(fn=>fn());root.classList.remove('is-enhanced');list.hidden=true;panels.forEach(p=>{p.hidden=false;p.removeAttribute('role');p.removeAttribute('aria-labelledby');p.removeAttribute('tabindex');});delete root.__naCleanup;};})();
</script>
